using Alterverse.Characters;using Alterverse.Combat;using UnityEngine;
namespace Alterverse.Visuals
{
public sealed class StylizedHeroVisual:MonoBehaviour
{
private HeroIdentity identity;private TeamMember team;private bool built;private void Start(){Build();}public void Build(){if(built)return;identity=GetComponent<HeroIdentity>();team=GetComponent<TeamMember>();if(identity==null)return;built=true;Color accent=StylizedArtDirection.HeroAccent(identity.Hero);Color dark=Color.Lerp(accent,StylizedArtDirection.Ink,.62f);Color teamEdge=team!=null&&team.Team==1?StylizedArtDirection.LumenEnergy:StylizedArtDirection.ZeroEnergy;CreatePart("DF_Torso",PrimitiveType.Cube,new Vector3(0,.22f,0),new Vector3(.62f,.72f,.48f),dark);CreatePart("DF_Head",PrimitiveType.Sphere,new Vector3(0,.82f,0),new Vector3(.62f,.52f,.62f),accent);switch(identity.Hero){case HeroId.Kaelon:CreatePart("DF_ShoulderL",PrimitiveType.Cube,new Vector3(-.58f,.38f,0),new Vector3(.55f,.32f,.74f),accent);CreatePart("DF_ShoulderR",PrimitiveType.Cube,new Vector3(.58f,.38f,0),new Vector3(.55f,.32f,.74f),accent);CreatePart("DF_Shield",PrimitiveType.Cube,new Vector3(-.72f,.02f,.28f),new Vector3(.12f,.9f,.72f),teamEdge);break;case HeroId.Nyra:CreatePart("DF_Rifle",PrimitiveType.Cube,new Vector3(.55f,.2f,.5f),new Vector3(.13f,.13f,1.45f),accent);CreatePart("DF_Sight",PrimitiveType.Cube,new Vector3(.55f,.38f,.48f),new Vector3(.18f,.12f,.22f),teamEdge);break;case HeroId.Elyra:CreatePart("DF_OrbitL",PrimitiveType.Sphere,new Vector3(.7f,.52f,0),Vector3.one*.23f,accent);CreatePart("DF_OrbitR",PrimitiveType.Sphere,new Vector3(-.7f,.28f,.15f),Vector3.one*.17f,teamEdge);break;case HeroId.Mira:CreatePart("DF_Wings",PrimitiveType.Cube,new Vector3(0,.34f,-.3f),new Vector3(1.42f,.11f,.42f),accent);CreatePart("DF_Bloom",PrimitiveType.Sphere,new Vector3(0,1.15f,0),Vector3.one*.2f,teamEdge);break;case HeroId.Rook:CreatePart("DF_GauntletL",PrimitiveType.Cube,new Vector3(-.62f,.05f,.22f),new Vector3(.46f,.5f,.65f),dark);CreatePart("DF_GauntletR",PrimitiveType.Cube,new Vector3(.62f,.05f,.22f),new Vector3(.58f,.58f,.75f),accent);break;default:CreatePart("DF_Blade",PrimitiveType.Cube,new Vector3(.55f,.15f,.3f),new Vector3(.12f,.95f,.15f),accent);CreatePart("DF_ShadowBlade",PrimitiveType.Cube,new Vector3(-.45f,.05f,.18f),new Vector3(.09f,.62f,.12f),teamEdge);break;}CreatePart("DF_TeamMark",PrimitiveType.Cylinder,new Vector3(0,-.9f,0),new Vector3(.72f,.018f,.72f),teamEdge);}
private void CreatePart(string n,PrimitiveType type,Vector3 pos,Vector3 scale,Color color){GameObject p=GameObject.CreatePrimitive(type);p.name=n;p.transform.SetParent(transform,false);p.transform.localPosition=pos;p.transform.localScale=scale;Collider c=p.GetComponent<Collider>();if(c!=null)c.enabled=false;Renderer r=p.GetComponent<Renderer>();if(r!=null)r.material.color=color;}
}
}
